-- The stats that count once per charge held (ChargeEffects.PerCharge, 92 stats) and the ones that count while the
-- character has none, or any, of a charge type (ChargeEffects.Conditional, 5 stats), as modifier rows with a new
-- column: "per" says what the stat counts ({"of":"power_charge"}; "charge": all three; "special": the type's
-- converted charges; "cap": the most the total can be; "when": "none" or "any" for the conditional ones), and the
-- row's quantity is the stat it adds to (one row for each). The charge code reads its two lists from these rows while
-- the effect rules are on, and from its own lists otherwise.
ALTER TABLE fx_modifiers ADD COLUMN per TEXT;
UPDATE fx_values SET built = 1, takes = 'of: endurance_charge, frenzy_charge, power_charge, charge (all three); special: the type''s converted charges; maximum: the type''s maximum; cap: the most the total can be; when: none or any',
    note = 'The value counts once for each of something the actor has. Built for charges: a modifier row''s "per" column, read by the charge code.'
WHERE id = 'per';
ON CONFLICT(stat, ord) DO UPDATE SET quantity = excluded.quantity, how = 'flat', per = excluded.per;
ON CONFLICT(stat) DO UPDATE SET handled = 'modifier', ref = excluded.ref, why = NULL, fit = NULL;
